/**
 * ⭐ **T-204 — the Firestore sync relay, on the same scheduler as month-end and the sweep.**
 * Closes DEF-132 (nothing ever called `drainOutbox`/`ingestEvents` against real Firestore) and
 * DEF-134 (nothing ever computed a fresh day's `attendance_days` row) with one job.
 *
 * ## ⚠️ The RLS-principal switch, and why it lives HERE rather than being imported
 *
 * Every existing request-serving code path in `apps/erp` applies row-level security through
 * `withOrgPrincipal` (`apps/erp/src/app/expenses/lib.ts`) — `set local role` + `set_config`
 * inside one Drizzle transaction. **That function is unreachable from this file**: this is
 * `packages/domain`, and bible §8 rule 13 (`tests/unit/app-boundaries.test.ts`) forbids a package
 * importing from an app. So this is a small package-local copy of the same three statements,
 * built from the same `@shareat/db` primitives (`APP_ROLE`, `transaction`) the app helper and the
 * integration test suites' own local `asOrg` helpers already use — this is the third independent
 * copy of an identical five-line idiom, which might be worth centralising in `@shareat/db`
 * someday; not this task's scope.
 *
 * ## ⚠️ Two lanes, two different relationships to "per org"
 *
 * **`mirror_publish` (Lane A) is genuinely per-org.** `mirror_outbox` rows already carry `org_id`
 * and its RLS policy (`org_column`, `packages/db/src/rls/registry.ts`) scopes `claimUnpublished`'s
 * unfiltered query down to one org for free the moment the transaction runs under that org's
 * principal — no code change to `publisher.ts`/`mirror-outbox.ts` needed. Looping per org (rather
 * than draining everything at once as `system`) is also what lets `DrainReport`'s own counts map
 * straight onto one `scheduler_runs` row per org, unmodified, per DEF-044's rule that even an
 * org with nothing to do still gets a row.
 *
 * **`inbox_relay` (Lane B) is NOT naturally per-org** — `/inbox` is one flat Firestore collection
 * and an event carries a `storeId`, never an `orgId`. Org membership is resolved in Postgres as a
 * `system` connection (RLS bypassed, sees every org's stores in one query — the same shape
 * `schedulerRepo.listOrgsToRun` already uses) BEFORE any org-scoped transaction opens; only once
 * an event's org is known does its batch run under that org's `withOrgPrincipal`. Getting this
 * backwards either has RLS silently return nothing (org-scoped too early, before the lookup can
 * see other orgs) or lets the ingest step see across orgs when it must not (system-scoped when it
 * should be org-scoped, which is exactly what would let `ingestEvents`'s `app_current_org()` call
 * write a quarantine row with no org at all — a NOT NULL violation, not a quiet bug).
 */
async function withOrgPrincipal<T>(orgId: string, fn: (tx: Tx) => Promise<T>): Promise<T> {
  return transaction(async (tx) => {
    await tx.execute(sql.raw(`set local role ${APP_ROLE}`));
    await tx.execute(sql`select set_config('app.principal_kind', 'staff', true)`);
    await tx.execute(sql`select set_config('app.org_id', ${orgId}, true)`);
    return fn(tx);
  });
}

export interface RelayResult {
  outcomes: JobOutcome[];
  hadFailures: boolean;
}

export async function runFirestoreRelay(
  drivers: { mirror: MirrorDriver; inbox: InboxDriver },
  options: { orgId?: string; trigger?: 'cron' | 'manual'; limit?: number } = {},
): Promise<RelayResult> {
  const trigger = options.trigger ?? 'cron';
  const limit = options.limit ?? 500;
  // ⚠️ Same reasoning as `runAttendanceSweep`: neither lane has a period of its own, so the row
  // records the YYYY-MM this run happened IN (PH local, UTC+8), not a period being closed.
  const period = new Date(Date.now() + 8 * 3_600_000).toISOString().slice(0, 7);

  const orgs = await transaction((tx) => schedulerRepo.listOrgsToRun(tx, options.orgId));
  const outcomes: JobOutcome[] = [];

  for (const org of orgs) {
    outcomes.push(await runMirrorPublishJob(org, period, trigger, drivers.mirror, limit));
  }

  outcomes.push(...(await runInboxRelayJobs(orgs, period, trigger, drivers.inbox, limit)));

  // ⚠️ Adjudication failures do NOT flip this. They are an expected, benign outcome (a replayed
  // old punch landing on a day payroll already closed) — visible on the outcome, but not the
  // thing a cron mailer should page anyone about. Only a genuine ingest/publish failure does.
  return { outcomes, hadFailures: outcomes.some((o) => o.failed > 0 || o.error) };
}

async function runMirrorPublishJob(
  org: { id: string; name: string },
  period: string,
  trigger: 'cron' | 'manual',
  driver: MirrorDriver,
  limit: number,
): Promise<JobOutcome> {
  const runId = await transaction((tx) =>
    schedulerRepo.startRun(tx, { orgId: org.id, job: 'mirror_publish', period, trigger }),
  );
  const base = { orgId: org.id, orgName: org.name, job: 'mirror_publish' as const, period };

  try {
    const report = await withOrgPrincipal(org.id, (tx) => drainOutbox(tx, driver, { limit }));

    // ⚠️ `DrainReport.failed` is a COUNT, not a list — the per-row detail already lives on
    // `mirror_outbox.last_error` (`recordFailure`), which this job does not re-read. `finishRun`
    // derives `scheduler_runs.failed_count` from `failures.length`, so the array below has to
    // carry exactly `report.failed` entries for that stored count to stay truthful, even though
    // each entry's own text is generic.
    const failures: SchedulerFailure[] = Array.from({ length: report.failed }, (_, i) => ({
      subjectId: org.id,
      subjectName: org.name,
      reason: `An outbox row failed to publish (see mirror_outbox.last_error) — failure ${i + 1} of ${report.failed}.`,
    }));

    await transaction((tx) =>
      schedulerRepo.finishRun(tx, runId, {
        postedCount: report.published,
        skippedCount: report.skipped,
        failures,
      }),
    );
    return { ...base, posted: report.published, skipped: report.skipped, failed: report.failed, failures };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    await transaction((tx) => schedulerRepo.failRun(tx, runId, message));
    return { ...base, posted: 0, skipped: 0, failed: 0, failures: [], error: message };
  }
}

type InboxDoc = { docId: string; data: unknown };

function eventStoreId(doc: InboxDoc): string | undefined {
  const storeId = (doc.data as { storeId?: unknown } | null)?.storeId;
  return typeof storeId === 'string' ? storeId : undefined;
}

function eventClientPunchId(doc: InboxDoc): string | undefined {
  const id = (doc.data as { clientPunchId?: unknown } | null)?.clientPunchId;
  return typeof id === 'string' ? id : undefined;
}

/**
 * One global read, then a per-org fan-out — see the module comment above for why Lane B cannot be
 * a simple per-org loop the way Lane A is.
 */
async function runInboxRelayJobs(
  orgs: { id: string; name: string }[],
  period: string,
  trigger: 'cron' | 'manual',
  driver: InboxDriver,
  limit: number,
): Promise<JobOutcome[]> {
  let events: InboxDoc[];
  try {
    events = await driver.readUnprocessed({ limit });
  } catch (err) {
    // The read itself blew up, before any org could even be attempted. Every org named in this
    // run still gets a row saying so — DEF-044's rule applies to the whole job, not just to a
    // per-org slice of it.
    const message = err instanceof Error ? err.message : String(err);
    return Promise.all(orgs.map((org) => failedInboxRun(org, period, trigger, message)));
  }

  const storeIds = [...new Set(events.map(eventStoreId).filter((s): s is string => s !== undefined))];
  const orgByStore = storeIds.length
    ? await transaction((tx) => storesRepo.orgIdsForStoreIds(tx, storeIds))
    : new Map<string, string>();

  // §3 step 3: a storeId matching no known store is left un-stamped and excluded from EVERY
  // group — it is simply never pushed anywhere below, so it is retried next run by construction.
  const byOrg = new Map<string, InboxDoc[]>();
  for (const doc of events) {
    const storeId = eventStoreId(doc);
    const orgId = storeId ? orgByStore.get(storeId) : undefined;
    if (!orgId) continue;
    if (!byOrg.has(orgId)) byOrg.set(orgId, []);
    byOrg.get(orgId)!.push(doc);
  }

  const outcomes: JobOutcome[] = [];
  for (const org of orgs) {
    outcomes.push(await runInboxRelayForOrg(org, period, trigger, driver, byOrg.get(org.id) ?? []));
  }
  return outcomes;
}

async function failedInboxRun(
  org: { id: string; name: string },
  period: string,
  trigger: 'cron' | 'manual',
  message: string,
): Promise<JobOutcome> {
  const runId = await transaction((tx) =>
    schedulerRepo.startRun(tx, { orgId: org.id, job: 'inbox_relay', period, trigger }),
  );
  await transaction((tx) => schedulerRepo.failRun(tx, runId, message));
  return {
    orgId: org.id,
    orgName: org.name,
    job: 'inbox_relay',
    period,
    posted: 0,
    skipped: 0,
    failed: 0,
    failures: [],
    error: message,
  };
}

async function runInboxRelayForOrg(
  org: { id: string; name: string },
  period: string,
  trigger: 'cron' | 'manual',
  driver: InboxDriver,
  events: InboxDoc[],
): Promise<JobOutcome> {
  const runId = await transaction((tx) =>
    schedulerRepo.startRun(tx, { orgId: org.id, job: 'inbox_relay', period, trigger }),
  );
  const base = { orgId: org.id, orgName: org.name, job: 'inbox_relay' as const, period };

  try {
    const report = await withOrgPrincipal(org.id, (tx) => ingestEvents(tx, events.map((e) => e.data)));

    // §3 step 5: EVERY event handed to `ingestEvents` gets exactly one outcome — ingested,
    // already-processed, quarantined, or discarded (T-182 invariant 4) — so every one of them is
    // "decided" and is stamped here. Only the unresolved-org group above (never reaching this
    // function at all) is left un-stamped. A discarded event is stamped too: a manager already
    // made that call in Postgres, and re-reading it forever on every future run would let a
    // devices's redelivery loop crowd a busy inbox's `limit` out on its own — nothing about
    // Firestore's `processedAt` flag is what would let that decision be reversed later; that
    // lives on `inbox_quarantine.resolved_at`/`resolution` in Postgres, untouched by this stamp.
    for (const doc of events) {
      const clientPunchId = eventClientPunchId(doc);
      const punchId = (clientPunchId && report.processed[clientPunchId]) || null;
      await driver.markProcessed({ docId: doc.docId, punchId });
    }

    // ⚠️ Same shape as `mirror_publish` above: `finishRun` derives `failed_count` from
    // `failures.length`, so this needs exactly `report.quarantined` entries. Unlike the mirror
    // job, real detail is available — `byReason` already breaks the count down by reason code.
    const failures: SchedulerFailure[] = [];
    for (const [reason, count] of Object.entries(report.byReason)) {
      for (let i = 0; i < (count ?? 0); i++) {
        failures.push({ subjectId: org.id, subjectName: org.name, reason: `quarantined: ${reason}` });
      }
    }

    await transaction((tx) =>
      schedulerRepo.finishRun(tx, runId, {
        postedCount: report.ingested,
        skippedCount: report.alreadyProcessed + report.refusedDiscarded,
        failures,
      }),
    );
    return {
      ...base,
      posted: report.ingested,
      skipped: report.alreadyProcessed + report.refusedDiscarded,
      failed: report.quarantined,
      failures,
      adjudicationFailures: report.adjudicationFailures.length ? report.adjudicationFailures : undefined,
    };
  } catch (err) {
    // ⭐ Covers both an `ingestEvents` failure outright AND a `markProcessed` write failure. The
    // latter is safe to let fail this org's run: whatever `ingestEvents` decided already committed
    // in Postgres (its own transaction returned before this loop starts), and every one of those
    // outcomes is idempotent on replay — a re-delivered already-ingested punch is a no-op, a
    // re-delivered quarantine upsert just bumps `attempts`. Retrying the whole org next run is the
    // safe, simple choice; a Firestore write outage is worth surfacing loudly (`error`, non-zero
    // exit), not swallowed per-event.
    const message = err instanceof Error ? err.message : String(err);
    await transaction((tx) => schedulerRepo.failRun(tx, runId, message));
    return { ...base, posted: 0, skipped: 0, failed: 0, failures: [], error: message };
  }
}

// =====================================================================================

/**
 * ⭐ **T-178 — the 15-day order-wastage backstop, on the same scheduler as everything above.**
 *
 * DEF-044's own lesson, restated for a new module: a job that exists but that nothing on any host
 * actually calls is indistinguishable, from the outside, from a job that was never built. This is
 * the ONLY thing that fires `runOrderWastageBackstop` — there is no separate cron path (task §11).
 *
 * ⚠️ Hourly-shaped like `attendance_sweep`, not monthly: a wastage's 15-day clock does not line up
 * with a calendar month, so `period` records the `YYYY-MM` this run happened IN, same convention
 * as the sweep and the Firestore relay above — never a period being closed.
 */
export interface OrderWastageBackstopResult {
  outcomes: JobOutcome[];
  hadFailures: boolean;
}

export async function runOrderWastageBackstopSweep(
  options: { orgId?: string; trigger?: 'cron' | 'manual'; nowMs?: number } = {},
): Promise<OrderWastageBackstopResult> {
  const trigger = options.trigger ?? 'cron';
  const nowMs = options.nowMs ?? Date.now();
  const period = new Date(nowMs + 8 * 3_600_000).toISOString().slice(0, 7);

  const orgs = await transaction((tx) => schedulerRepo.listOrgsToRun(tx, options.orgId));
  const outcomes: JobOutcome[] = [];
  for (const org of orgs) {
    outcomes.push(await runOrderWastageBackstopForOrg(org, period, trigger, nowMs));
  }
  return { outcomes, hadFailures: outcomes.some((o) => o.failed > 0 || o.error) };
}

async function runOrderWastageBackstopForOrg(
  org: { id: string; name: string },
  period: string,
  trigger: 'cron' | 'manual',
  nowMs: number,
): Promise<JobOutcome> {
  const runId = await transaction((tx) =>
    schedulerRepo.startRun(tx, { orgId: org.id, job: 'order_wastage_backstop', period, trigger }),
  );
  const base = { orgId: org.id, orgName: org.name, job: 'order_wastage_backstop' as const, period };

  try {
    // ⚠️ One transaction for the WHOLE org's due wastages, not one per row — invariant 11's
    // period-lock refusal and invariant 12's idempotency both flow through the shared `postEntry`
    // called inside; a single wastage whose channel is unconfigured is caught per-row inside
    // `runOrderWastageBackstop` (`failures`), which does not abort the rest of the batch.
    const result = await transaction((tx) =>
      runOrderWastageBackstop(tx, org.id, { now: new Date(nowMs), postedBy: null }),
    );
    const failures: SchedulerFailure[] = result.failures.map((f) => ({
      subjectId: f.wastageId,
      subjectName: `order wastage ${f.wastageId}`,
      reason: f.reason,
    }));
    await transaction((tx) =>
      schedulerRepo.finishRun(tx, runId, {
        postedCount: result.outcomes.length,
        skippedCount: 0,
        failures,
      }),
    );
    return { ...base, posted: result.outcomes.length, skipped: 0, failed: failures.length, failures };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    await transaction((tx) => schedulerRepo.failRun(tx, runId, message));
    return { ...base, posted: 0, skipped: 0, failed: 0, failures: [], error: message };
  }
}

/**
 * ⭐ **T-214 — the daily finding-observation run.**
 *
 * Findings are a pure function of current state and carry no clock, so *when* a condition first
 * appeared is not recoverable from anywhere. This job is the clock: once a day it records that each
 * detector fired, and closes the occurrences that stopped firing.
 *
 * ⛔ **It exists as a scheduler job specifically so it cannot become DEF-186** — `replenishAfterUsage`
 * was built, tested, marked done, and invoked by nothing for weeks. ⚠️ And registering the job is
 * still not the finish line: `docs/ops/README.md` carries the timer, and DEF-044 is what a job with
 * no armed timer costs.
 *
 * ⚠️ `scheduler_runs.period` is shaped `YYYY-MM` by a CHECK, and a daily job has no month of its
 * own, so it records the Manila month it RAN in — the same choice `runAttendanceSweep` makes and for
 * the same reason.
 */
export async function runFindingObservation(
  options: { orgId?: string; trigger?: 'cron' | 'manual'; nowMs?: number } = {},
): Promise<SweepResult> {
  const trigger = options.trigger ?? 'cron';
  const nowMs = options.nowMs ?? Date.now();
  const period = new Date(nowMs + 8 * 3_600_000).toISOString().slice(0, 7);

  const orgs = await transaction((tx) => schedulerRepo.listOrgsToRun(tx, options.orgId));
  const outcomes: JobOutcome[] = [];

  // ⛔ One org at a time, and one org failing must never stop the next — T-140 rule 1.
  for (const org of orgs) {
    const runId = await transaction((tx) =>
      schedulerRepo.startRun(tx, { orgId: org.id, job: 'finding_observation', period, trigger }),
    );
    const base = { orgId: org.id, orgName: org.name, job: 'finding_observation' as const, period };

    try {
      // ⚠️ ONE transaction per org, unlike month-end's per-item transactions. The whole point is a
      // consistent daily snapshot: observing half the detectors and closing occurrences against the
      // other half would invent clears that never happened.
      const result = await transaction(async (tx) => {
        await tx.execute(sql.raw(`set local role ${APP_ROLE}`));
        await tx.execute(sql`select set_config('app.principal_kind', 'system', true)`);
        await tx.execute(sql`select set_config('app.org_id', ${org.id}, true)`);
        return recordFindingObservations(tx, org.id, new Date(nowMs));
      });

      await transaction((tx) =>
        schedulerRepo.finishRun(tx, runId, {
          postedCount: result.opened,
          skippedCount: result.observed - result.opened,
          failures: [],
        }),
      );
      outcomes.push({
        ...base,
        posted: result.opened,
        skipped: result.observed - result.opened,
        failed: 0,
        failures: [],
        detail: `asked ${result.periodsAsked.join(', ')} · observed ${result.observed} · opened ${result.opened} · closed ${result.closed}`,
      });
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e);
      await transaction((tx) => schedulerRepo.failRun(tx, runId, message));
      outcomes.push({ ...base, posted: 0, skipped: 0, failed: 0, failures: [], error: message });
    }
  }

  return { outcomes, hadFailures: outcomes.some((o) => o.failed > 0 || o.error) };
}

/**
 * One transaction, run as the SYSTEM principal for one org.
 *
 * ⭐ Extracted for `budget_reissue` (T-215) and deliberately per-CALL rather than one transaction
 * around the whole org: `reference_postgres_batch_needs_savepoint` — one DB error aborts the
 * transaction it happened in, so a single bad budget inside a shared transaction would take the
 * run's own `scheduler_runs` write down with it and the failure would leave no trace at all.
 */
async function asSystem<T>(orgId: string, fn: (tx: Tx) => Promise<T>): Promise<T> {
  return transaction(async (tx) => {
    await tx.execute(sql.raw(`set local role ${APP_ROLE}`));
    await tx.execute(sql`select set_config('app.principal_kind', 'system', true)`);
    await tx.execute(sql`select set_config('app.org_id', ${orgId}, true)`);
    return fn(tx);
  });
}

/**
 * `budget_reissue` — T-215, DAILY. Rolls an expense envelope forward so nobody has to remember to
 * recreate it.
 *
 * ## Two interval families, and only one of them creates a row
 *
 * - **RESET** (`daily`, `weekly`, `bi_weekly`) — the same budget keeps going and its WINDOW moves.
 *   ⭐ Consumption is derived, so there is no counter to zero; what changes is `last_reset_at`.
 *   v1 had to mutate a stored number to do this, which is why its reset could not be replayed.
 * - **PERIOD** (`monthly`, `quarterly`, `annually`) — insert the NEXT period's row, carrying the
 *   same amount and config, **only once that period has actually arrived.**
 *
 * ⛔ **The restraint is ported verbatim, comment and all.** v1: *"never pre-create future months,
 * so the reissue processor can't run away."* A job that creates the next twelve months on its
 * first run has invented eleven caps nobody agreed to, and every one of them looks authoritative.
 *
 * ## ⭐ Idempotent as a database FACT, not as a promise
 *
 * `insertReissued` is `ON CONFLICT DO NOTHING` against the unique envelope, so a second run the
 * same day creates nothing and does not throw. ⚠️ **One transaction per budget**, deliberately —
 * bible §13 and `reference_postgres_batch_needs_savepoint`: one DB error aborts the whole
 * transaction it happened in, so a per-row failure inside a shared transaction would take the
 * run's own `scheduler_runs` write down with it and the failure would be invisible.
 *
 * ## ⚠️ Catch-up is bounded, and the bound is not arbitrary
 *
 * A monthly budget last reissued in January and a job that has not run since needs eleven rows,
 * not one — so the loop advances until it reaches the current period. It is capped at 24 hops:
 * beyond two years something is wrong with the data, and a runaway insert loop is worse than an
 * unreissued budget.
 */
export async function runBudgetReissue(
  options: { orgId?: string; trigger?: 'cron' | 'manual'; nowMs?: number } = {},
): Promise<SweepResult> {
  const trigger = options.trigger ?? 'cron';
  const nowMs = options.nowMs ?? Date.now();
  const now = new Date(nowMs);
  // Manila, the same +8 shift every other job in this file uses.
  const manila = new Date(nowMs + 8 * 3_600_000).toISOString().slice(0, 10);
  const period = manila.slice(0, 7);
  const currentPeriodKey = period.replace('-', '');

  const orgs = await transaction((tx) => schedulerRepo.listOrgsToRun(tx, options.orgId));
  const outcomes: JobOutcome[] = [];

  for (const org of orgs) {
    const runId = await transaction((tx) =>
      schedulerRepo.startRun(tx, { orgId: org.id, job: 'budget_reissue', period, trigger }),
    );
    const base = { orgId: org.id, orgName: org.name, job: 'budget_reissue' as const, period };
    const failures: SchedulerFailure[] = [];
    let created = 0;
    let reset = 0;
    let skipped = 0;

    try {
      const budgets = await asSystem(org.id, (tx) => budgetsRepo.listAutoReissuing(tx, org.id));

      // ⭐ Only the NEWEST period per (store, category) is a candidate. Without this an old row
      // keeps re-proposing a period that already exists — harmless because of the unique index,
      // and it would still mean the job's counters said "skipped" for ever while nobody noticed
      // the chain had stopped advancing. `listAutoReissuing` orders period_key desc, so the first
      // one seen for a key is the newest.
      const newest = new Map<string, (typeof budgets)[number]>();
      for (const b of budgets) {
        const key = `${b.storeId}:${b.categoryId}`;
        if (!newest.has(key)) newest.set(key, b);
      }

      for (const b of newest.values()) {
        try {
          const interval = b.reissueInterval;
          // Unreachable while `expense_budgets_reissue_interval_check` holds; kept because a
          // narrowing that relies on a database constraint should still be explicit in code.
          if (interval === null) {
            skipped += 1;
            continue;
          }

          const windowDays = resetWindowDays(interval);
          if (windowDays !== null) {
            // ---- RESET family: move the window, create nothing. --------------------------
            const startedAt =
              b.lastResetAt ?? new Date(`${b.periodKey.slice(0, 4)}-${b.periodKey.slice(4, 6)}-01T00:00:00Z`);
            const elapsedDays = Math.floor((now.getTime() - startedAt.getTime()) / 86_400_000);
            if (elapsedDays < windowDays) {
              skipped += 1;
              continue;
            }
            // ⚠️ Advance by WHOLE windows from where the last one started, never to "now". Stamping
            // `now` would let the window drift by however late the job ran, so a daily cap would
            // slowly become a 25-hour one and a reader comparing two stores would see neither.
            const hops = Math.floor(elapsedDays / windowDays);
            const advanced = new Date(startedAt.getTime() + hops * windowDays * 86_400_000);
            await asSystem(org.id, (tx) => budgetsRepo.stampReset(tx, org.id, b.id, advanced));
            reset += 1;
            continue;
          }

          // ---- PERIOD family: create the next row, once it has arrived. -------------------
          let from = b;
          let key = nextPeriodKey(b.periodKey, interval);
          let hops = 0;
          let madeAny = false;
          while (key !== null && key <= currentPeriodKey && hops < 24) {
            const row = await asSystem(org.id, (tx) =>
              budgetsRepo.insertReissued(tx, {
                orgId: org.id,
                storeId: from.storeId,
                categoryId: from.categoryId,
                periodKey: key!,
                amount: from.amount,
                autoReissue: from.autoReissue,
                reissueInterval: from.reissueInterval,
                reissuedFromId: from.id,
                createdBy: null,
              }),
            );
            if (row) {
              created += 1;
              madeAny = true;
              from = { ...from, id: row.id, periodKey: key };
            } else {
              // Already there — a second run today, or a hand-set cap for that period. Either way
              // the chain continues from it rather than stopping.
              from = { ...from, periodKey: key };
            }
            key = nextPeriodKey(key, interval);
            hops += 1;
          }
          if (!madeAny) skipped += 1;
        } catch (e) {
          failures.push({
            subjectId: b.id,
            // ⚠️ The store and category, not the uuid — a failure line nobody can act on without
            // a database session is a failure line nobody acts on.
            subjectName: `store ${b.storeId} · category ${b.categoryId} · ${b.periodKey}`,
            reason: e instanceof Error ? e.message : String(e),
          });
        }
      }

      await transaction((tx) =>
        schedulerRepo.finishRun(tx, runId, { postedCount: created, skippedCount: skipped, failures }),
      );
      outcomes.push({
        ...base,
        posted: created,
        skipped,
        failed: failures.length,
        failures,
        detail: `budgets ${newest.size} · created ${created} · windows moved ${reset} · nothing due ${skipped}`,
      });
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e);
      await transaction((tx) => schedulerRepo.failRun(tx, runId, message));
      outcomes.push({ ...base, posted: 0, skipped: 0, failed: 0, failures: [], error: message });
    }
  }

  return { outcomes, hadFailures: outcomes.some((o) => o.failed > 0 || o.error) };
}
